content.text:
{
  "name": "SiTCP传输层组件",
  "name_en": "SiTCP Transport Layer Component",
  "manufacturer": "",
  "description": "一个非物理的软件通信组件，通过以太网使用 TCP 和 UDP/RBCP 协议与外部实验电子学或 FPGA 寄存器总线通信。它用于初始化连接、读写总线地址、复位缓冲区或 FIFO，并在实验数据采集系统中管理套接字与读出流程。",
  "description_en": "A non-physical software communication component that talks over Ethernet using TCP and UDP/RBCP to external lab electronics or FPGA register buses. It is used to initialize connections, read and write bus addresses, reset buffers or FIFOs, and manage sockets and readout flow in experimental data acquisition systems.",
  "actions": [
    {
      "action_name": "auto-reset",
      "description": "复位 SiTCP 通信状态或相关缓冲状态。",
      "description_en": "Reset the SiTCP communication state or related buffer state."
    },
    {
      "action_name": "auto-reset_fifo",
      "description": "复位 SiTCP 数据 FIFO 缓冲区。",
      "description_en": "Reset the SiTCP data FIFO buffer."
    },
    {
      "action_name": "auto-init",
      "description": "初始化 SiTCP 传输连接、套接字监控和读出线程。",
      "description_en": "Initialize the SiTCP transport connection, socket monitoring, and readout thread."
    },
    {
      "action_name": "auto-write",
      "description": "向指定总线地址写入数据。",
      "description_en": "Write data to a specified bus address."
    },
    {
      "action_name": "auto-read",
      "description": "从指定总线地址读取数据。",
      "description_en": "Read data from a specified bus address."
    },
    {
      "action_name": "auto-close",
      "description": "关闭 SiTCP 连接和相关通信资源。",
      "description_en": "Close the SiTCP connection and related communication resources."
    }
  ],
  "tag_hints": [
    "SiTCP",
    "Ethernet transport",
    "RBCP",
    "TCP bus access",
    "FPGA register communication",
    "data acquisition",
    "socket readout"
  ]
}

